#!/usr/bin/env python3
"""Build the V3 decision catalogs for five evidence-reviewed industries.

The role roster below is the human-reviewed source of truth.  The generator keeps
the original V1 employee identity (idx/person), carries forward audited V2 sources,
adds direct official evidence for the reviewed V3 pain clusters, and compiles every
role into the existing no-side-effect decision contract.  It intentionally does not
load application code so it can be reviewed and run in isolation.
"""

from __future__ import annotations

import argparse
from difflib import SequenceMatcher
import hashlib
import json
import re
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
V1_DIR = ROOT / "data" / "departments"
V2_DIR = ROOT / "data" / "industry_decisions"
OUT_DIR = ROOT / "data" / "industry_decisions_v3"
CATALOG_VERSION = "2026.08.v3"
AS_OF = "2026-08-12"
DECISION_STATES = ["GO", "HOLD", "ESCALATE", "ADVISE"]
GO_SEMANTICS = "证据足以进入人工审批，不代表允许系统执行任何业务写操作"


