def _rows(block: str, default_pain: str) -> list[tuple[str, str]]:
    result = []
    for raw in block.strip().splitlines():
        value = raw.strip()
        if not value:
            continue
        name, marker, pain = value.partition("|")
        result.append((name.strip(), pain.strip() if marker else default_pain))
    return result


def parse_role_assets(block: str) -> dict[str, dict]:
    result: dict[str, dict] = {}
    for raw in block.strip().splitlines():
        fields = [value.strip() for value in raw.split("|")]
        if len(fields) != 9:
            raise ValueError(f"role asset must have 9 fields: {raw}")
        name, decision, inputs, outputs, metric_name, metric_formula, steps, score, cadence = fields
        result[name] = {
            "decision": decision,
            "inputs": [value.strip() for value in inputs.split("；")],
            "outputs": [value.strip() for value in outputs.split("；")],
            "metric_name": metric_name,
            "metric_formula": metric_formula,
            "middle_steps": [value.strip() for value in steps.split("；")],
            "score": [int(value) for value in score.split(",")],
            "cadence": cadence,
        }
    if len(result) != 36:
        raise ValueError(f"role assets cardinality={len(result)}")
    return result


def parse_pain_clusters(block: str) -> tuple[dict, ...]:
    result = []
    for raw in block.strip().splitlines():
        fields = [value.strip() for value in raw.split("|")]
        if len(fields) != 8:
            raise ValueError(f"pain cluster must have 8 fields: {raw}")
        code, group, title, why, signals, decisions, required_data, sources = fields
        result.append({
            "code": code,
            "group": group,
            "title": title,
            "why": why,
            "signals": [value.strip() for value in signals.split("；")],
            "decisions": [value.strip() for value in decisions.split("；")],
            "required_data": [value.strip() for value in required_data.split("；")],
            "source_ids": [value.strip() for value in sources.split(",")],
        })
    if len(result) != 8:
        raise ValueError(f"pain clusters cardinality={len(result)}")
    return tuple(result)


def parse_professional_assets(block: str) -> dict[str, dict]:
    result: dict[str, dict] = {}
    for raw in block.strip().splitlines():
        fields = [value.strip() for value in raw.split("|")]
        if len(fields) != 17:
            raise ValueError(f"professional asset must have 17 fields: {raw}")
        (
            name, tools, knowledge, skills, capabilities,
            daily, event_driven, review,
            hold_owner, hold_action, escalate_owner, escalate_action,
            role, duty, desc, intro, rationale,
        ) = fields
        parsed_tools = []
        for tool in tools.split("；"):
            tool_name, marker, scope = tool.partition("@")
            if not marker or not tool_name.strip() or not scope.strip():
                raise ValueError(f"{name}: malformed tool {tool}")
            parsed_tools.append({
                "tool": tool_name.strip(),
                "access": "read_only",
                "scope": scope.strip(),
            })
        result[name] = {
            "tool_permissions": parsed_tools,
            "knowledge_domains": [value.strip() for value in knowledge.split("；")],
            "skill_tree": [value.strip() for value in skills.split("；")],
            "capabilities": [value.strip() for value in capabilities.split("；")],
            "operating_rhythm": {
                "daily": daily,
                "event_driven": event_driven,
                "review": review,
            },
            "hold_owner": hold_owner,
            "hold_action": hold_action,
            "escalate_owner": escalate_owner,
            "escalate_action": escalate_action,
            "role": role,
            "duty": duty,
            "desc": desc,
            "intro": intro,
            "selection_rationale": rationale,
        }
    if len(result) != 36:
        raise ValueError(f"professional assets cardinality={len(result)}")
    return result


def parse_extra_metrics(block: str) -> dict[str, list[dict[str, str]]]:
    result: dict[str, list[dict[str, str]]] = {}
    for raw in block.strip().splitlines():
        fields = [value.strip() for value in raw.split("|")]
        if len(fields) != 5:
            raise ValueError(f"extra metrics must have 5 fields: {raw}")
        name, metric_two_name, metric_two_formula, metric_three_name, metric_three_formula = fields
        if name in result:
            raise ValueError(f"duplicate extra metrics: {name}")
        result[name] = [
            {"name": metric_two_name, "formula": metric_two_formula},
            {"name": metric_three_name, "formula": metric_three_formula},
        ]
    if len(result) != 36:
        raise ValueError(f"extra metrics cardinality={len(result)}")
    return result


def parse_escalation_conditions(block: str) -> dict[str, dict[str, str]]:
    result: dict[str, dict[str, str]] = {}
    for raw in block.strip().splitlines():
        fields = [value.strip() for value in raw.split("|")]
        if len(fields) != 3:
            raise ValueError(f"escalation conditions must have 3 fields: {raw}")
        name, hold_condition, escalate_condition = fields
        if name in result:
            raise ValueError(f"duplicate escalation conditions: {name}")
        result[name] = {
            "hold": hold_condition,
            "escalate": escalate_condition,
        }
    if len(result) != 36:
        raise ValueError(f"escalation conditions cardinality={len(result)}")
    return result


def parse_full_role_assets(block: str) -> tuple[
    dict[str, dict], dict[str, dict],
    dict[str, list[dict[str, str]]], dict[str, dict[str, str]],
]:
    role_assets: dict[str, dict] = {}
    professional_assets: dict[str, dict] = {}
    extra_metrics: dict[str, list[dict[str, str]]] = {}
    escalation_assets: dict[str, dict[str, str]] = {}
    for raw in block.strip().splitlines():
        fields = [value.strip() for value in raw.split("|")]
        if len(fields) != 19:
            raise ValueError(f"full role asset must have 19 fields: {raw}")
        (
            name, decision, inputs_raw, outputs_raw, metric_name,
            metric_formula, extra_raw, steps_raw, score_raw, cadence,
            tools_raw, knowledge_raw, skills_raw, capabilities_raw,
            rhythm_daily, rhythm_event, rhythm_review,
            escalation_raw, bios_raw,
        ) = fields
        inputs = [value.strip() for value in inputs_raw.split("；")]
        outputs = [value.strip() for value in outputs_raw.split("；")]
        steps = [value.strip() for value in steps_raw.split("；")]
        score = [int(value) for value in score_raw.split(",")]
        if len(inputs) != 3 or len(outputs) != 2 or len(steps) != 2 or len(score) != 4:
            raise ValueError(f"{name}: malformed role contract vectors")
        parsed_extra = []
        for metric in extra_raw.split("；"):
            metric_extra_name, marker, metric_extra_formula = metric.partition("~")
            if not marker:
                raise ValueError(f"{name}: malformed extra metric {metric}")
            parsed_extra.append({
                "name": metric_extra_name.strip(),
                "formula": metric_extra_formula.strip(),
            })
        if len(parsed_extra) != 2:
            raise ValueError(f"{name}: expected two extra metrics")
        tools = []
        for tool in tools_raw.split("；"):
            tool_name, marker, scope = tool.partition("@")
            if not marker:
                raise ValueError(f"{name}: malformed tool {tool}")
            tools.append({"tool": tool_name, "access": "read_only", "scope": scope})
        knowledge = [value.strip() for value in knowledge_raw.split("；")]
        skills = [value.strip() for value in skills_raw.split("；")]
        capabilities = [value.strip() for value in capabilities_raw.split("；")]
        escalation_rows = [value.strip() for value in escalation_raw.split("；")]
        bios = [value.strip() for value in bios_raw.split("；")]
        if (
            len(tools) < 2 or len(knowledge) < 3 or len(skills) < 5
            or len(capabilities) < 4
            or len(escalation_rows) != 2 or len(bios) != 5
        ):
            raise ValueError(f"{name}: malformed professional vectors")
        escalation_values = []
        for escalation in escalation_rows:
            parts = [value.strip() for value in escalation.split("~")]
            if len(parts) != 3:
                raise ValueError(f"{name}: malformed escalation {escalation}")
            escalation_values.append(parts)
        role_assets[name] = {
            "decision": decision, "inputs": inputs, "outputs": outputs,
            "metric_name": metric_name, "metric_formula": metric_formula,
            "middle_steps": steps, "score": score, "cadence": cadence,
        }
        professional_assets[name] = {
            "tool_permissions": tools,
            "knowledge_domains": knowledge,
            "skill_tree": skills,
            "capabilities": capabilities,
            "operating_rhythm": {
                "daily": rhythm_daily,
                "event_driven": rhythm_event,
                "review": rhythm_review,
            },
            "hold_owner": escalation_values[0][1],
            "hold_action": escalation_values[0][2],
            "escalate_owner": escalation_values[1][1],
            "escalate_action": escalation_values[1][2],
            "role": bios[0], "duty": bios[1], "desc": bios[2],
            "intro": bios[3], "selection_rationale": bios[4],
        }
        extra_metrics[name] = parsed_extra
        escalation_assets[name] = {
            "hold": escalation_values[0][0],
            "escalate": escalation_values[1][0],
        }
    if len(role_assets) != 36:
        raise ValueError(f"full role assets cardinality={len(role_assets)}")
    return role_assets, professional_assets, extra_metrics, escalation_assets


