def complete_pharmacy_bios(block: str) -> str:
    completed = []
    for raw in block.strip().splitlines():
        fields = raw.split("|")
        name = fields[0].strip()
        bios = [value.strip() for value in fields[18].split("；")]
        if name in PHARMACY_INTRO_COMPLETIONS:
            if len(bios) != 4:
                raise ValueError(f"{name}: expected four source bios before completion")
            bios.insert(3, PHARMACY_INTRO_COMPLETIONS[name])
            fields[18] = "；".join(bios)
        completed.append("|".join(fields))
    return "\n".join(completed)


