def _kind(name: str) -> str:
    if any(token in name for token in ("需求", "预测", "容量", "客流", "备货")):
        return "forecast"
    if any(token in name for token in ("成本", "净值", "毛利", "盈亏", "贡献", "结算", "价格", "清价", "返利", "坪效", "核算")):
        return "economics"
    if any(token in name for token in ("追溯", "标签", "对账", "完整", "证据", "真实性", "记录", "差异归因", "一键追溯")):
        return "trace"
    if any(token in name for token in ("风险", "门禁", "安全", "食安", "卫生", "许可", "证照", "召回", "危机", "温", "过敏", "相互作用", "剂量", "转诊", "不良反应", "特殊管理", "异常", "防损", "治安")):
        return "risk"
    if any(token in name for token in ("排班", "站位", "瓶颈", "调度", "补货", "分货", "调拨", "波次", "节流", "配送", "履约", "产能", "配置", "营业时长", "恢复", "绕行")):
        return "operations"
    if any(token in name for token in ("会员", "复购", "召回", "篮子", "场景", "权益", "频次", "留存")):
        return "customer"
    return "governance"


def _decision(name: str, kind: str) -> str:
    core = name[:-1] if name.endswith("官") else name
    templates = {
        "forecast": f"{core}应采用哪个可回放需求情景，以及该情景是否具备进入人工计划审批的证据",
        "economics": f"{core}方案的全量经济口径与敏感性是否完整，是否具备进入人工审批的净价值",
        "trace": f"{core}所需对象、时间、责任与原始凭证能否闭合为可追溯证据链",
        "risk": f"{core}是否满足适用准入与风险边界，应该GO、HOLD、ESCALATE还是仅ADVISE",
        "operations": f"{core}在容量、技能、时窗与安全硬约束下应选择哪个人工执行方案",
        "customer": f"{core}面向哪一可授权人群与场景产生可验证增量价值，并在何种条件下停止",
        "governance": f"{core}的候选方案是否有足够事实、对照与责任边界进入人工审批",
    }
    return templates[kind]


def _workflow(name: str, kind: str) -> list[str]:
    core = name[:-1] if name.endswith("官") else name
    middle = {
        "forecast": ["按门店、时段和事件切分历史需求", "回放候选情景并量化偏差与不确定性"],
        "economics": ["还原含税、优惠、损耗、履约与资金时间的全量口径", "比较基线、候选方案与关键参数敏感性"],
        "trace": ["按对象、批次、时间和责任人串联原始凭证", "定位断链、冲突、迟录与不可逆变更"],
        "risk": ["逐项核对适用规则、企业制度与硬性红线", "对异常分级并验证隔离、升级和复核证据"],
        "operations": ["建立容量、技能、时窗和安全约束矩阵", "模拟候选方案对等待、品质与负荷的影响"],
        "customer": ["核对授权状态并定义目标场景和观察窗", "用对照识别自然发生、蚕食与真实增量"],
        "governance": ["对齐决策范围、候选项和责任边界", "核验事实、对照、依赖与反证"],
    }[kind]
    return [
        f"锁定{core}的门店、对象、时间窗、版本和授权责任人",
        *middle,
        f"形成{core}的GO、HOLD、ESCALATE与ADVISE判定依据",
        "输出带来源索引、待补证据、审批人和复盘日期的只读建议",
    ]


def _metric(idx: int, core: str, suffix: str, name: str, formula: str, inputs: list[str]) -> dict:
    return {
        "key": f"v3_{idx}_{suffix}",
        "name": f"{core}{name}",
        "formula": formula,
        "window": "每月；按门店或业务单元分层，保留分子、分母、N/A原因和对象级明细",
        "source": f"{inputs[0]}、{inputs[1]}，以及{core}批准口径字典、原始凭证、审批记录、执行日志和复核日志",
        "baseline_policy": "同口径采用本企业最近4个完整统计窗口的中位数；不足4个窗口标记“基线不足”，不得用行业值或臆测值补齐",
        "target_policy": "由有权负责人依据本企业同口径基线、风险容忍度和适用要求书面批准；目录不预设行业阈值",
    }


def _metrics(idx: int, name: str, kind: str, inputs: list[str]) -> list[dict]:
    core = name[:-1] if name.endswith("官") else name
    dimension = {
        "forecast": ("情景回放覆盖率", "完成同口径历史回放且保留误差明细的候选情景数 ÷ 同期纳入评审的候选情景总数 × 100%；分母为0时记N/A"),
        "economics": ("全量经济口径完整率", "收入、优惠、成本、损耗、履约和资金时间字段齐备的评审对象数 ÷ 同期应评审对象总数 × 100%；分母为0时记N/A"),
        "trace": ("关键链路可追溯率", "对象、批次、时间、责任人与原始凭证完整关联的记录数 ÷ 同期应关联记录总数 × 100%；分母为0时记N/A"),
        "risk": ("风险证据完整率", "适用规则、原始事实、分级依据和复核责任均齐备的风险事项数 ÷ 同期应评审风险事项总数 × 100%；分母为0时记N/A"),
        "operations": ("硬约束入模完整率", "容量、技能、时窗和安全硬约束均进入方案比较的评审数 ÷ 同期应评审方案总数 × 100%；分母为0时记N/A"),
        "customer": ("授权与增量证据完整率", "授权状态、目标场景、观察窗和对照证据均齐备的人群方案数 ÷ 同期应评审人群方案总数 × 100%；分母为0时记N/A"),
        "governance": ("决策证据完整率", "事实、口径、反证、责任人和复盘日期均齐备的决策事项数 ÷ 同期应评审事项总数 × 100%；分母为0时记N/A"),
    }[kind]
    return [
        _metric(idx, core, "m1", dimension[0], dimension[1], inputs),
        _metric(idx, core, "m2", "建议可解释率", "已关联原始事实、计算口径、反证和人工复核结论的建议数 ÷ 同期输出建议总数 × 100%；分母为0时记N/A", inputs),
        _metric(idx, core, "m3", "到期复盘闭环率", "在批准期限内完成结果验证且保留偏差原因的事项数 ÷ 同期到期应复盘事项总数 × 100%；分母为0时记N/A", inputs),
    ]


def explicit_metric(
    industry: str,
    idx: int,
    suffix: str,
    name: str,
    formula: str,
    window: str,
    sources: list[str],
) -> dict:
    return {
        "key": f"{industry}_v3_{idx}_{suffix}",
        "name": name,
        "formula": formula,
        "window": window,
        "source": "；".join(sources),
        "baseline_policy": "同口径采用本企业最近4个完整统计窗口的中位数；不足4个窗口标记“基线不足”，不得用行业值或臆测值补齐",
        "target_policy": "由有权负责人依据本企业同口径基线、风险容忍度和适用要求书面批准；目录不预设行业阈值",
    }


def explicit_profile(
    asset: dict,
    professional: dict,
    outputs: list[str],
    escalation_conditions: dict[str, str],
) -> dict:
    decision = asset["decision"]
    inputs = asset["inputs"]
    return {
        "scope": (
            f"{professional['role']}的职责域：围绕{professional['knowledge_domains'][0]}"
            f"与{professional['knowledge_domains'][1]}，以{inputs[0]}和{inputs[1]}为核心对象，"
            f"负责{professional['capabilities'][0]}、{professional['capabilities'][1]}；"
            f"{professional['desc']}；只提供分析和审批材料，不执行门店业务写操作。"
        ),
        "decisions": [
            decision,
            professional.get("secondary_decision") or (
                f"当证据不足时是否由{professional['hold_owner']}执行“{professional['hold_action']}”，"
                f"或升级给{professional['escalate_owner']}处置。"
            ),
        ],
        "knowledge_domains": professional["knowledge_domains"],
        "data_objects": inputs[:3],
        "tool_permissions": professional["tool_permissions"],
        "skill_tree": professional["skill_tree"],
        "capabilities": professional["capabilities"],
        "operating_rhythm": professional["operating_rhythm"],
        "escalation_matrix": [
            {
                "level": "HOLD",
                "condition": escalation_conditions["hold"],
                "owner": professional["hold_owner"],
                "action": professional["hold_action"],
            },
            {
                "level": "ESCALATE",
                "condition": escalation_conditions["escalate"],
                "owner": professional["escalate_owner"],
                "action": professional["escalate_action"],
            },
        ],
        "learning_tracks": [
            professional["knowledge_domains"][0],
            professional["skill_tree"][2],
            professional["capabilities"][3],
        ],
    }


def explicit_employee(
    industry: str,
    idx: int,
    person: str,
    name: str,
    group_name: str,
    emoji: str,
    color: str,
    pain: dict,
    role_assets: dict[str, dict],
    professional_assets: dict[str, dict],
    extra_metrics: dict[str, list[dict[str, str]]],
    escalation_assets: dict[str, dict[str, str]],
) -> dict:
    asset = role_assets[name]
    professional = professional_assets[name]
    decision = asset["decision"]
    inputs = [
        *asset["inputs"],
        f"{asset['outputs'][0]}采用的候选规则、情景、责任人、批准边界和有效版本",
    ]
    outputs = asset["outputs"]
    score_values = asset["score"]
    if len(score_values) != 4:
        raise ValueError(f"{name}: priority score needs 4 dimensions")
    priority_score = {
        "pain_severity": score_values[0],
        "usage_frequency": score_values[1],
        "economic_value": score_values[2],
        "data_availability": score_values[3],
        "total": sum(score_values),
    }
    workflow = [
        professional["skill_tree"][0],
        asset["middle_steps"][0],
        professional["skill_tree"][1],
        professional["skill_tree"][2],
        asset["middle_steps"][1],
        professional["skill_tree"][3],
        professional["skill_tree"][4],
    ]
    role_metric_extensions = extra_metrics[name]
    tools = professional["tool_permissions"]
    rhythm = professional["operating_rhythm"]
    metrics = [
        explicit_metric(
            industry, idx, "native", asset["metric_name"], asset["metric_formula"],
            f"{asset['cadence']}；{rhythm['review']}时由“{professional['capabilities'][0]}”"
            f"校验“{professional['knowledge_domains'][0]}”的统计边界，保留对象级分子、分母与N/A原因",
            [
                inputs[0], inputs[1],
                f"{tools[0]['tool']}只读取数范围：{tools[0]['scope']}",
            ],
        ),
        explicit_metric(
            industry, idx, "native2",
            role_metric_extensions[0]["name"], role_metric_extensions[0]["formula"],
            f"{rhythm['daily']}；{rhythm['review']}时执行“{professional['skill_tree'][2]}”，"
            f"按“{professional['knowledge_domains'][1]}”所需的异常类型和对照窗复算",
            [
                inputs[1], inputs[2],
                f"{tools[1]['tool']}只读取数范围：{tools[1]['scope']}",
            ],
        ),
        explicit_metric(
            industry, idx, "native3",
            role_metric_extensions[1]["name"], role_metric_extensions[1]["formula"],
            f"{rhythm['event_driven']}；{rhythm['review']}后用“{professional['skill_tree'][4]}”"
            f"评估“{professional['capabilities'][3]}”，并封存事件前后对象明细",
            [
                inputs[0], inputs[2],
                f"{tools[0]['tool']}与{tools[1]['tool']}的对象主键、版本及人工执行结果",
            ],
        ),
    ]
    total = priority_score["total"]
    value_grade = "极高价值" if total >= 19 else "高价值" if total >= 17 else "重点价值" if total >= 15 else "专业保障"
    profile = explicit_profile(
        asset, professional, outputs, escalation_assets[name]
    )
    return {
        "idx": idx,
        "num": idx,
        "key": f"{industry.replace('_', '-')}-v3-{idx}",
        "name": name,
        "person": person,
        "role": professional["role"],
        "duty": professional["duty"],
        "desc": professional["desc"],
        "intro": professional["intro"],
        "emoji": emoji,
        "color": color,
        "group": group_name,
        "pain_codes": [pain["code"]],
        "primary_decision": decision,
        "priority_score": priority_score,
        "priority_rank": 0,
        "value_grade": value_grade,
        "usage_cadence": asset["cadence"],
        "selection_rationale": professional["selection_rationale"],
        "professional_profile": profile,
        "decision_contract": {
            "decision": decision,
            "decision_states": DECISION_STATES,
            "triggers": [
                f"按“{asset['cadence']}”进入计划、承诺、放行或复盘节点",
                f"{inputs[0]}出现断档，或{inputs[1]}发生异常、冲突和版本变化",
            ],
            "required_inputs": inputs,
            "evidence_required": [
                f"{inputs[0]}必须保留对象标识、时间戳、数据源和责任人",
                f"{inputs[1]}与{inputs[2]}必须能够回放{asset['middle_steps'][0]}的过程和反证",
            ],
            "workflow": workflow,
            "outputs": outputs,
            "success_metrics": metrics,
            "approval_boundary": f"本岗位只生成{outputs[0]}、{outputs[1]}和风险解释；与“{decision}”有关的采购、定价、排班、库存、触达、准入、资金、许可或系统写操作均由有权人员审批执行。",
            "forbidden_actions": [
                f"不得绕过人工审批直接执行{outputs[0]}中的候选结论",
                f"不得在{inputs[0]}或{inputs[1]}缺失冲突时强行返回GO",
                "不得补造、删除、覆盖原始证据或以无来源行业均值替代企业事实",
                "不得扩张数据处理目的、写入外部系统或对客户作未经批准的承诺",
            ],
            "fallback": f"{inputs[0]}、{inputs[1]}、{inputs[2]}或{inputs[3]}不完整时返回HOLD并形成{outputs[1]}；涉及重大食品安全、人身、资金、隐私、许可或连续经营风险时返回ESCALATE。",
            "requires_human_approval": True,
            "allowed_side_effects": [],
            "go_semantics": GO_SEMANTICS,
        },
        "public_guide": {
            "focus": decision,
            "materials": "；".join(inputs) + "。",
            "input_tips": [
                f"注明门店、对象、时间窗，以及希望人工决定的“{decision}”",
                f"上传{inputs[0]}并保留来源、版本、时间戳和缺失项",
                f"补充{inputs[1]}与{inputs[2]}，标明红线、审批人和复盘日期",
            ],
            "output_hint": f"将得到{outputs[0]}与{outputs[1]}；系统不会直接执行任何业务写操作。",
        },
    }


def _canonical_employee_text(value: object, employee: dict, industry: str) -> str:
    text = json.dumps(value, ensure_ascii=False, sort_keys=True) if not isinstance(value, str) else value
    core = employee["name"][:-1] if employee["name"].endswith("官") else employee["name"]
    for token in sorted(
        {employee["name"], core, employee["person"], employee["key"], str(employee["idx"]), industry, industry.replace("_", "-")},
        key=len,
        reverse=True,
    ):
        text = text.replace(token, "<ROLE>")
    return re.sub(r"[\s‘’“”\"、，。；：:/()（）·+×÷−—_\-]+", "", text).lower()


def _canonical_profile_skeleton(value: object, employee: dict, industry: str) -> str:
    text = json.dumps(value, ensure_ascii=False, sort_keys=True)
    removal = {
        employee["name"], employee["name"][:-1], employee["person"],
        employee["key"], str(employee["idx"]), industry,
        industry.replace("_", "-"), employee["group"],
        employee["primary_decision"],
        *employee["decision_contract"]["required_inputs"],
        *employee["decision_contract"]["outputs"],
        *(metric["name"] for metric in employee["decision_contract"]["success_metrics"]),
    }
    for token in sorted(removal, key=len, reverse=True):
        if token:
            text = text.replace(token, "<X>")
    return re.sub(r"[\s‘’“”\"、，。；：:/()（）·+×÷−—_\-]+", "", text).lower()


def _canonical_contract_skeleton(value: object, employee: dict, industry: str) -> str:
    text = json.dumps(value, ensure_ascii=False, sort_keys=True)
    profile = employee["professional_profile"]
    contract = employee["decision_contract"]
    removal = {
        employee["name"], employee["name"][:-1], employee["person"],
        employee["key"], str(employee["idx"]), industry,
        industry.replace("_", "-"), employee["group"],
        employee["primary_decision"], employee["usage_cadence"],
        *contract["required_inputs"], *contract["outputs"],
        *(metric["name"] for metric in contract["success_metrics"]),
        *(metric["formula"] for metric in contract["success_metrics"]),
        *profile["data_objects"],
    }
    for token in sorted(removal, key=len, reverse=True):
        if token:
            text = text.replace(token, "<X>")
    return re.sub(r"[\s‘’“”\"、，。；：:/()（）·+×÷−—_\-]+", "", text).lower()


def _canonical_escalation_condition(value: str, employee: dict, industry: str) -> str:
    text = value
    profile = employee["professional_profile"]
    contract = employee["decision_contract"]
    removal = {
        employee["name"], employee["name"][:-1], employee["person"],
        employee["key"], str(employee["idx"]), industry,
        industry.replace("_", "-"), employee["group"],
        employee["primary_decision"], employee["usage_cadence"],
        *contract["required_inputs"], *contract["outputs"],
        *(metric["name"] for metric in contract["success_metrics"]),
        *(metric["formula"] for metric in contract["success_metrics"]),
        *profile["capabilities"],
        *(tool["tool"] for tool in profile["tool_permissions"]),
        *(tool["scope"] for tool in profile["tool_permissions"]),
        *(row["owner"] for row in profile["escalation_matrix"]),
        *(row["action"] for row in profile["escalation_matrix"]),
    }
    for token in sorted(removal, key=len, reverse=True):
        if token:
            text = text.replace(token, "<X>")
    return re.sub(r"[\s‘’“”\"、，。；：:/()（）·+×÷−—_\-]+", "", text).lower()


def _similarity_gate(values: list[str], label: str, limit: float = 0.80) -> dict:
    if len(values) != len(set(values)):
        raise ValueError(f"canonical duplicate: {label} unique={len(set(values))}/{len(values)}")
    similarities = sorted(
        SequenceMatcher(None, values[left], values[right], autojunk=False).ratio()
        for left in range(len(values))
        for right in range(left + 1, len(values))
    )
    maximum = similarities[-1]
    p95 = similarities[int((len(similarities) - 1) * 0.95)]
    if maximum >= limit:
        left, right, _ = _most_similar_pair(values)
        raise ValueError(
            f"similarity red: {label} max={maximum:.4f} >= {limit:.2f} "
            f"pair={left + 1},{right + 1}"
        )
    return {
        "unique": len(set(values)), "total": len(values),
        "p95": round(p95, 4), "max": round(maximum, 4),
    }


def _most_similar_pair(values: list[str]) -> tuple[int, int, float]:
    best = (-1, -1, -1.0)
    for left in range(len(values)):
        for right in range(left + 1, len(values)):
            ratio = SequenceMatcher(
                None, values[left], values[right], autojunk=False
            ).ratio()
            if ratio > best[2]:
                best = (left, right, ratio)
    return best


def anti_copy_audit(industry: str, employees: list[dict]) -> dict:
    projections = {
        "decision": lambda e: e["primary_decision"],
        "required_inputs": lambda e: e["decision_contract"]["required_inputs"],
        "workflow": lambda e: e["decision_contract"]["workflow"],
        "outputs": lambda e: e["decision_contract"]["outputs"],
        "native_metric": lambda e: e["decision_contract"]["success_metrics"][0]["formula"],
        "three_native_metrics": lambda e: [
            [metric["name"], metric["formula"]]
            for metric in e["decision_contract"]["success_metrics"]
        ],
        "skill_tree": lambda e: e["professional_profile"]["skill_tree"],
        "capabilities": lambda e: e["professional_profile"]["capabilities"],
        "knowledge_domains": lambda e: e["professional_profile"]["knowledge_domains"],
        "tool_permissions": lambda e: e["professional_profile"]["tool_permissions"],
        "operating_rhythm": lambda e: e["professional_profile"]["operating_rhythm"],
        "escalation_matrix": lambda e: e["professional_profile"]["escalation_matrix"],
        "learning_tracks": lambda e: e["professional_profile"]["learning_tracks"],
    }
    stats: dict[str, dict] = {}
    for field, getter in projections.items():
        values = [_canonical_employee_text(getter(employee), employee, industry) for employee in employees]
        if len(values) != len(set(values)):
            raise ValueError(f"{industry} canonical duplicate: {field}")
        stats[field] = {"unique": len(set(values)), "total": len(values)}
    for field in (
        "knowledge_domains", "tool_permissions", "skill_tree", "capabilities",
        "operating_rhythm", "escalation_matrix", "learning_tracks",
    ):
        values = [
            _canonical_profile_skeleton(e["professional_profile"][field], e, industry)
            for e in employees
        ]
        similarities = sorted(
            SequenceMatcher(None, values[left], values[right], autojunk=False).ratio()
            for left in range(len(values))
            for right in range(left + 1, len(values))
        )
        maximum = similarities[-1]
        p95 = similarities[int((len(similarities) - 1) * 0.95)]
        if len(values) != len(set(values)) or maximum >= 0.80:
            raise ValueError(
                f"{industry} professional skeleton red: {field} "
                f"unique={len(set(values))}/{len(values)} max={maximum:.4f}"
            )
        stats[f"{field}_skeleton"] = {
            "unique": len(set(values)), "total": len(values),
            "p95": round(p95, 4), "max": round(maximum, 4),
        }
    workflow_values = [
        _canonical_contract_skeleton(e["decision_contract"]["workflow"], e, industry)
        for e in employees
    ]
    stats["workflow_skeleton"] = _similarity_gate(
        workflow_values, f"{industry}:workflow_skeleton"
    )
    workflow_length = len(employees[0]["decision_contract"]["workflow"])
    if any(len(e["decision_contract"]["workflow"]) != workflow_length for e in employees):
        raise ValueError(f"{industry}: workflow length mismatch")
    for position in range(workflow_length):
        values = [
            _canonical_contract_skeleton(
                e["decision_contract"]["workflow"][position], e, industry
            )
            for e in employees
        ]
        stats[f"workflow_step_{position + 1}_skeleton"] = _similarity_gate(
            values, f"{industry}:workflow_step_{position + 1}"
        )
    metric_count = len(employees[0]["decision_contract"]["success_metrics"])
    if metric_count != 3 or any(
        len(e["decision_contract"]["success_metrics"]) != metric_count
        for e in employees
    ):
        raise ValueError(f"{industry}: every role needs exactly three native metrics")
    for position in range(metric_count):
        metric_name_formula = [
            _canonical_employee_text(
                {
                    "name": e["decision_contract"]["success_metrics"][position]["name"],
                    "formula": e["decision_contract"]["success_metrics"][position]["formula"],
                },
                e,
                industry,
            )
            for e in employees
        ]
        stats[f"metric_{position + 1}_name_formula"] = _similarity_gate(
            metric_name_formula, f"{industry}:metric_{position + 1}_name_formula"
        )
        metric_skeleton = [
            _canonical_contract_skeleton(
                {
                    key: e["decision_contract"]["success_metrics"][position][key]
                    for key in ("name", "formula", "window", "source")
                },
                e,
                industry,
            )
            for e in employees
        ]
        stats[f"metric_{position + 1}_skeleton"] = _similarity_gate(
            metric_skeleton, f"{industry}:metric_{position + 1}_skeleton"
        )
    for position, level in enumerate(("hold", "escalate")):
        values = [
            _canonical_escalation_condition(
                e["professional_profile"]["escalation_matrix"][position]["condition"],
                e,
                industry,
            )
            for e in employees
        ]
        stats[f"{level}_condition_stripped_skeleton"] = _similarity_gate(
            values, f"{industry}:{level}_condition_stripped"
        )
    bodies = [
        _canonical_employee_text(
            [e["role"], e["duty"], e["desc"], e["intro"]], e, industry
        )
        for e in employees
    ]
    similarities = [
        SequenceMatcher(None, bodies[left], bodies[right], autojunk=False).ratio()
        for left in range(len(bodies))
        for right in range(left + 1, len(bodies))
    ]
    similarities.sort()
    maximum = similarities[-1]
    p95 = similarities[int((len(similarities) - 1) * 0.95)]
    if maximum >= 0.80:
        raise ValueError(f"{industry} duty-body similarity max={maximum:.4f} >= 0.80")
    stats["duty_body"] = {"p95": round(p95, 4), "max": round(maximum, 4)}
    return stats


