def validate_source_semantics(industry: str, sources: list[dict], pain_clusters: tuple[dict, ...]) -> None:
    source_by_id = {row["id"]: row for row in sources}
    if len(source_by_id) != len(sources):
        raise ValueError(f"{industry}: duplicate source id")
    pain_by_code = {row["code"]: row for row in pain_clusters}
    for pain in pain_clusters:
        unknown = set(pain["source_ids"]) - set(source_by_id)
        if unknown:
            raise ValueError(f"{industry}/{pain['code']}: unknown source ids {sorted(unknown)}")

    for source_id, required_tokens in SOURCE_TITLE_REQUIREMENTS.items():
        if source_id not in source_by_id:
            continue
        title = source_by_id[source_id]["title"]
        missing = [token for token in required_tokens if token not in title]
        if missing:
            raise ValueError(f"{industry}/{source_id}: title missing semantic tokens {missing}")

    if industry == "convenience":
        if set(pain_by_code) != set(CONVENIENCE_EXPECTED_SOURCE_IDS):
            raise ValueError("convenience: semantic source matrix must cover exactly 8 V3 pain clusters")
        for pain_code, expected in CONVENIENCE_EXPECTED_SOURCE_IDS.items():
            actual = tuple(pain_by_code[pain_code]["source_ids"])
            if actual != expected:
                raise ValueError(f"convenience/{pain_code}: sources {actual} != reviewed matrix {expected}")
            for source_id in actual:
                if pain_code not in CONVENIENCE_SOURCE_SUPPORTS.get(source_id, set()):
                    raise ValueError(f"convenience/{pain_code}: {source_id} has no direct semantic support")
        restricted = set(pain_by_code["CVV3-LICENSE-RESTRICTED"]["source_ids"])
        if not {"CV-S4", "CV-S5"} <= restricted:
            raise ValueError("convenience: restricted sales must cite tobacco permit and minors law")
        for pain_code, pain in pain_by_code.items():
            if pain_code != "CVV3-LICENSE-RESTRICTED" and ({"CV-S4", "CV-S5"} & set(pain["source_ids"])):
                raise ValueError(f"convenience/{pain_code}: tobacco/minors sources are bound outside restricted sales")

    for pain_code, required_ids in REQUIRED_SOURCE_BINDINGS.get(industry, {}).items():
        missing = required_ids - set(pain_by_code[pain_code]["source_ids"])
        if missing:
            raise ValueError(f"{industry}/{pain_code}: missing direct sources {sorted(missing)}")
    for source_id, allowed_pain in EXCLUSIVE_SOURCE_BINDINGS.get(industry, {}).items():
        uses = [pain["code"] for pain in pain_clusters if source_id in pain["source_ids"]]
        if uses != [allowed_pain]:
            raise ValueError(f"{industry}/{source_id}: expected exclusive binding to {allowed_pain}, got {uses}")


def build_explicit_catalog(
    industry: str,
    industry_specs: dict,
    role_assets: dict[str, dict],
    professional_assets: dict[str, dict],
    extra_metrics: dict[str, list[dict[str, str]]],
    escalation_assets: dict[str, dict[str, str]],
    pain_clusters: tuple[dict, ...],
    additional_sources: tuple[dict, ...] = (),
) -> dict:
    spec = industry_specs[industry]
    v1 = json.loads((V1_DIR / f"{industry}.json").read_text(encoding="utf-8"))
    v2 = json.loads((V2_DIR / f"{industry}.json").read_text(encoding="utf-8"))
    people = {int(row["idx"]): row["person"] for row in v1["employees"]}
    pain_by_group = {row["group"]: row for row in pain_clusters}
    groups = []
    employees = []
    idx = spec["start"]
    for group_name, emoji, color, _default_pain, block in spec["groups"]:
        pain = pain_by_group[group_name]
        members = []
        for name, _old_pain in _rows(block, "unused"):
            employees.append(explicit_employee(
                industry, idx, people[idx], name, group_name, emoji, color,
                pain, role_assets, professional_assets, extra_metrics,
                escalation_assets,
            ))
            members.append(idx)
            idx += 1
        groups.append({"name": group_name, "emoji": emoji, "color": color, "members": members})
    ranked = sorted(
        employees,
        key=lambda row: (
            -row["priority_score"]["total"],
            -row["priority_score"]["usage_frequency"],
            -row["priority_score"]["economic_value"],
            -row["priority_score"]["pain_severity"],
            -row["priority_score"]["data_availability"],
            row["idx"],
        ),
    )
    for rank, row in enumerate(ranked, 1):
        row["priority_rank"] = rank
    sources = [*v2["sources"], *additional_sources]
    validate_source_semantics(industry, sources, pain_clusters)
    catalog = {
        "key": industry,
        "name": spec["name"],
        "emoji": v2["emoji"],
        "tagline": spec["tagline"],
        "catalog_version": CATALOG_VERSION,
        "as_of": AS_OF,
        "identity_policy": "保留V1原始idx与person；V3为当前岗位版本，历史任务继续冻结其原岗位版本。",
        "selection_policy": "按痛点严重度、使用频率、经济价值和企业数据可得性筛选并排序36个非重复专属岗位。",
        "sources": sources,
        "pain_points": [{k: v for k, v in pain.items() if k != "group"} for pain in pain_clusters],
        "groups": groups,
        "employees": employees,
    }
    audit = anti_copy_audit(industry, employees)
    catalog["quality_audit"] = {
        "method": "移除员工name/core/person/industry/idx后做职责字段精确指纹与正文SequenceMatcher审计",
        **audit,
    }
    return catalog


def _build_tea() -> dict:
    return build_explicit_catalog(
        "tea_coffee", INDUSTRIES, TEA_ASSETS, TEA_PROFESSIONAL, TEA_EXTRA,
        TEA_ESCALATIONS, TEA_PAIN_CLUSTERS, TEA_ADDITIONAL_SOURCES,
    )


