def _employee(industry: str, idx: int, person: str, name: str, group: str, pain: dict) -> dict:
    kind = _kind(name)
    core = name[:-1] if name.endswith("官") else name
    inputs = list(dict.fromkeys([
        *pain["required_data"],
        f"{core}当前候选方案、适用范围、版本、责任人与批准时间窗",
        f"{core}相关原始明细、异常记录、变更日志与既往人工结论",
    ]))[:8]
    while len(inputs) < 4:
        inputs.append(f"{core}补充事实证据第{len(inputs) + 1}项")
    decision = _decision(name, kind)
    workflow = _workflow(name, kind)
    outputs = [f"{core}四态决策单", f"{core}证据索引、缺口与人工审批包"]
    return {
        "idx": idx,
        "num": idx,
        "key": f"{industry.replace('_', '-')}-v3-{idx}",
        "name": name,
        "person": person,
        "role": f"{INDUSTRIES[industry]['name']}·{name}",
        "duty": f"围绕“{decision}”持续核验企业事实，形成可执行但不自动执行的行业建议。",
        "desc": f"专职解决{pain['title']}中的{core}问题，不代理审批、不修改业务系统、不用行业均值替代企业证据。",
        "intro": f"{person}是{core}的专属数字员工，负责把原始业务数据整理成可追溯、可复核、可复盘的人工决策材料。",
        "emoji": INDUSTRIES[industry]["groups"][next(i for i, g in enumerate(INDUSTRIES[industry]["groups"]) if g[0] == group)][1],
        "color": INDUSTRIES[industry]["groups"][next(i for i, g in enumerate(INDUSTRIES[industry]["groups"]) if g[0] == group)][2],
        "group": group,
        "pain_codes": [pain["code"]],
        "primary_decision": decision,
        "decision_contract": {
            "decision": decision,
            "decision_states": DECISION_STATES,
            "triggers": [
                f"进入{core}计划、变更、放行或复盘节点前",
                f"出现“{pain['signals'][0]}”或相关数据口径冲突时",
            ],
            "required_inputs": inputs,
            "evidence_required": [
                f"{core}对象级原始记录、口径版本与来源索引",
                f"{core}候选方案、反证、人工审批责任与复盘时间证据",
            ],
            "workflow": workflow,
            "outputs": outputs,
            "success_metrics": _metrics(idx, name, kind, inputs),
            "approval_boundary": f"仅输出{core}建议和证据缺口；任何采购、定价、排班、库存、客户触达、准入放行、资金、许可或系统写操作均由有权人员审批执行。",
            "forbidden_actions": [
                f"自动执行{core}结论或代替有权人员审批",
                "补造、篡改、删除或覆盖原始业务证据",
                "证据不足、口径冲突或越过硬约束时强行给出GO",
                "以无来源行业均值、模型猜测或个人敏感信息替代本企业批准口径",
            ],
            "fallback": f"{core}的对象、时间窗、关键输入、来源索引或责任边界不完整时HOLD并列出缺口；涉及安全、质量、许可、欺诈、隐私或重大经营风险时ESCALATE。",
            "requires_human_approval": True,
            "allowed_side_effects": [],
            "go_semantics": GO_SEMANTICS,
        },
        "public_guide": {
            "focus": decision,
            "materials": "；".join(inputs[:6]) + "。",
            "input_tips": [
                f"先说明{core}的门店、对象、时间窗和当前候选方案",
                "上传对象级原始明细并注明数据源、口径版本和缺失项",
                "标明必须遵守的硬约束、授权审批人和期望复盘日期",
            ],
            "output_hint": f"将得到{outputs[0]}和{outputs[1]}；系统不会直接执行任何业务写操作。",
        },
    }


def build(industry: str) -> dict:
    if industry == "tea_coffee":
        return _build_tea()
    if industry == "convenience":
        return _build_convenience()
    if industry == "snack":
        return _build_snack()
    if industry == "grocery":
        return _build_grocery()
    if industry == "pharmacy":
        return _build_pharmacy()
    spec = INDUSTRIES[industry]
    v1 = json.loads((V1_DIR / f"{industry}.json").read_text(encoding="utf-8"))
    v2 = json.loads((V2_DIR / f"{industry}.json").read_text(encoding="utf-8"))
    people = {int(row["idx"]): row["person"] for row in v1["employees"]}
    pains = {row["code"]: row for row in v2["pain_points"]}
    groups = []
    employees = []
    idx = spec["start"]
    for group_name, emoji, color, default_pain, block in spec["groups"]:
        members = []
        for name, pain_code in _rows(block, default_pain):
            if pain_code not in pains:
                raise ValueError(f"{industry}/{name}: unknown pain {pain_code}")
            if idx not in people:
                raise ValueError(f"{industry}: V1 employee {idx} is missing")
            employees.append(_employee(industry, idx, people[idx], name, group_name, pains[pain_code]))
            members.append(idx)
            idx += 1
        groups.append({"name": group_name, "emoji": emoji, "color": color, "members": members})
    result = {
        "key": industry,
        "name": spec["name"],
        "emoji": v2["emoji"],
        "tagline": spec["tagline"],
        "catalog_version": CATALOG_VERSION,
        "as_of": AS_OF,
        "identity_policy": "保留V1原始idx与person；V3为当前岗位版本，历史任务继续冻结其原岗位版本。",
        "selection_policy": "仅保留本行业高频、高价值、可获得企业事实且有明确人工决策边界的36个专属岗位。",
        "sources": v2["sources"],
        "pain_points": v2["pain_points"],
        "groups": groups,
        "employees": employees,
    }
    validate_catalog(result, spec["start"])
    return result


def validate_catalog(catalog: dict, start: int) -> None:
    employees = catalog["employees"]
    if len(employees) != 36:
        raise ValueError(f"{catalog['key']}: expected 36 employees, got {len(employees)}")
    if [row["idx"] for row in employees] != list(range(start, start + 36)):
        raise ValueError(f"{catalog['key']}: employee ids are not continuous")
    members = [idx for group in catalog["groups"] for idx in group["members"]]
    if members != list(range(start, start + 36)):
        raise ValueError(f"{catalog['key']}: groups do not cover roster exactly")
    for employee in employees:
        contract = employee["decision_contract"]
        if not 4 <= len(contract["required_inputs"]) <= 8:
            raise ValueError(f"{employee['idx']}: required_inputs outside 4..8")
        if len(contract["evidence_required"]) < 2 or len(contract["workflow"]) < 4:
            raise ValueError(f"{employee['idx']}: evidence/workflow incomplete")
        if len(contract["outputs"]) < 2 or len(contract["success_metrics"]) != 3:
            raise ValueError(f"{employee['idx']}: outputs/metrics incomplete")
        if len(contract["forbidden_actions"]) < 3 or contract["allowed_side_effects"] != []:
            raise ValueError(f"{employee['idx']}: unsafe contract")
        if contract["decision_states"] != DECISION_STATES or contract["go_semantics"] != GO_SEMANTICS:
            raise ValueError(f"{employee['idx']}: invalid decision states")
        for metric in contract["success_metrics"]:
            if not re.fullmatch(r"[a-z][a-z0-9_]{2,63}", metric["key"]):
                raise ValueError(f"{employee['idx']}: invalid metric key")


def validate_global(catalogs: list[dict]) -> None:
    employees = [row for catalog in catalogs for row in catalog["employees"]]
    checks = {
        "idx": [row["idx"] for row in employees],
        "key": [row["key"] for row in employees],
        "name": [row["name"] for row in employees],
        "primary_decision": [row["primary_decision"] for row in employees],
        "outputs": [tuple(row["decision_contract"]["outputs"]) for row in employees],
        "metric_names": [tuple(item["name"] for item in row["decision_contract"]["success_metrics"]) for row in employees],
    }
    for field, values in checks.items():
        if len(values) != len(set(values)):
            dupes = sorted({value for value in values if values.count(value) > 1}, key=str)
            raise ValueError(f"global duplicate {field}: {dupes[:3]}")
    metrics = [
        metric
        for employee in employees
        for metric in employee["decision_contract"]["success_metrics"]
    ]
    for field in ("key", "name", "formula"):
        values = [metric[field] for metric in metrics]
        if len(values) != len(set(values)):
            duplicate = next(value for value in values if values.count(value) > 1)
            raise ValueError(f"global duplicate metric {field}: {duplicate}")


def render(catalog: dict) -> str:
    return json.dumps(catalog, ensure_ascii=False, indent=2) + "\n"


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true", help="compare generated bytes with checked-in JSON")
    parser.add_argument("--industry", choices=tuple(INDUSTRIES), help="generate/check only one industry")
    args = parser.parse_args()
    selected = (args.industry,) if args.industry else tuple(INDUSTRIES)
    catalogs = [build(industry) for industry in selected]
    validate_global(catalogs)
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    for catalog in catalogs:
        target = OUT_DIR / f"{catalog['key']}.json"
        payload = render(catalog)
        if args.check:
            if not target.exists() or target.read_text(encoding="utf-8") != payload:
                raise SystemExit(f"OUT-OF-DATE {target}")
        else:
            target.write_text(payload, encoding="utf-8")
        digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()
        print(f"{catalog['key']}\t36\t{digest}")
    print(f"TOTAL\t{sum(len(c['employees']) for c in catalogs)}\tUNIQUE")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
